/**
 * Shared layout for every Reporty email: the app notifications sent through Resend and the
 * Supabase Auth templates generated by `scripts/generate-auth-email-templates.ts`.
 *
 * The look is a postcard from Posadas: the coastal map the app uses as its backdrop, the logo
 * pinned on it like a map label, and the report shown as a numbered file card. Email clients
 * ignore CSS variables and most modern CSS, so the theme tokens from `app/globals.css` live
 * here as hex values and the markup uses tables with inline styles. Web fonts and the reveal
 * animation are progressive: clients that drop them (Gmail, Outlook) still get a readable email.
 *
 * No `server-only` marker: the generator script imports this module outside Next.
 */

/** `app/globals.css` tokens converted from OKLCH to hex. */
export const EMAIL_COLORS = {
  background: "#eeecec",
  card: "#ffffff",
  foreground: "#15140f",
  mutedForeground: "#495a4f",
  subtle: "#f6f5f4",
  border: "#e2e0e0",
  primary: "#278c5a",
  primaryOnDark: "#6ad8a1",
  accent: "#d8eee0",
  accentForeground: "#163524",
  destructive: "#cc3d3d",
  info: "#297cae",
  button: "#000000",
} as const

const FONT_SANS = "'Geist', 'Segoe UI', 'Helvetica Neue', Helvetica, Arial, sans-serif"
const FONT_MONO = "'Geist Mono', 'SFMono-Regular', Menlo, Consolas, monospace"
const FONTS_URL = "https://fonts.googleapis.com/css2?family=Geist:wght@400;600;700&family=Geist+Mono:wght@500;600&display=swap"

export type EmailTone = "success" | "danger" | "info"

const TONE_COLORS: Record<EmailTone, string> = {
  success: EMAIL_COLORS.primary,
  danger: EMAIL_COLORS.destructive,
  info: EMAIL_COLORS.info,
}

export function escapeHtml(value: string) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;")
}

/** Small uppercase monospace label, the "file card" voice of the layout. */
function monoLabel(tag: "p" | "span", text: string, color: string, extraStyle = "") {
  const style = `font-family:${FONT_MONO};font-size:11px;font-weight:600;letter-spacing:1.6px;color:${color};${extraStyle}`
  return `<${tag} style="${style}">${escapeHtml(text.toLocaleUpperCase("es"))}</${tag}>`
}

/** A paragraph of body copy. `html` must already be escaped. */
export function emailParagraph(html: string) {
  return `<p style="margin:0 0 16px 0;font-family:${FONT_SANS};font-size:16px;line-height:1.6;color:${EMAIL_COLORS.mutedForeground};">${html}</p>`
}

/** Uppercase status pill, like the report state badges in the app. */
export function emailPill(label: string, tone: EmailTone) {
  return monoLabel("span", label, "#ffffff", `display:inline-block;padding:5px 12px;border-radius:999px;background:${TONE_COLORS[tone]};`)
}

/**
 * The report as a numbered file card: monospace eyebrow, title and a tone-colored edge.
 * `title` is plain text; `content` is already-escaped HTML placed under it.
 */
export function emailPanel({
  eyebrow,
  title,
  content,
  tone,
}: {
  eyebrow?: string
  title: string
  content?: string
  tone?: EmailTone
}) {
  const edge = tone ? TONE_COLORS[tone] : EMAIL_COLORS.border
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" class="rp-rise rp-d2" style="margin:8px 0 24px 0;border-collapse:separate;">
  <tr>
    <td style="padding:20px 22px;border-radius:18px;background:${EMAIL_COLORS.subtle};border:1px solid ${EMAIL_COLORS.border};border-left:5px solid ${edge};">
      ${eyebrow ? monoLabel("p", eyebrow, edge, "margin:0 0 6px 0;") : ""}
      <p style="margin:0;font-family:${FONT_SANS};font-size:18px;font-weight:600;line-height:1.35;letter-spacing:-0.2px;color:${EMAIL_COLORS.foreground};">${escapeHtml(title)}</p>
      ${content ?? ""}
    </td>
  </tr>
</table>`
}

/** A labelled value inside a panel, such as the new state or a comment. `value` is escaped HTML. */
export function emailField(label: string, value: string) {
  return `${monoLabel("p", label, EMAIL_COLORS.mutedForeground, "margin:16px 0 4px 0;")}
      <p style="margin:0;font-family:${FONT_SANS};font-size:15px;line-height:1.6;color:${EMAIL_COLORS.foreground};white-space:pre-wrap;">${value}</p>`
}

/** Black pill call to action, the main control style of the app, with a green arrow. */
export function emailButton(label: string, href: string) {
  return `<table role="presentation" cellpadding="0" cellspacing="0" class="rp-rise rp-d3" style="margin:8px 0 20px 0;">
  <tr>
    <td style="border-radius:999px;background:${EMAIL_COLORS.button};">
      <a href="${href}" style="display:inline-block;padding:14px 26px;border-radius:999px;font-family:${FONT_SANS};font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;">${escapeHtml(label)}&nbsp;&nbsp;<span style="color:${EMAIL_COLORS.primaryOnDark};">&rarr;</span></a>
    </td>
  </tr>
</table>`
}

type EmailLayoutOptions = {
  /** Origin that serves `public/`: the app URL, or `{{ .SiteURL }}` in Supabase templates. */
  assetBaseUrl: string
  /** Document title and accessible name. */
  title: string
  /** Inbox preview text shown next to the subject. */
  preheader: string
  /** Short monospace label above the heading, e.g. "Nuevo comentario". */
  kicker: string
  heading: string
  /** Escaped HTML built with the helpers above. */
  body: string
  /** Small print under the card. Escaped HTML. */
  footnote?: string
}

export function renderEmailLayout({ assetBaseUrl, title, preheader, kicker, heading, body, footnote }: EmailLayoutOptions) {
  const mapUrl = `${assetBaseUrl}/email/posadas-mapa.jpg`
  const logoUrl = `${assetBaseUrl}/email/reporty-logo.png`

  return `<!DOCTYPE html>
<html lang="es">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="color-scheme" content="light">
    <meta name="supported-color-schemes" content="light">
    <title>${escapeHtml(title)}</title>
    <link href="${FONTS_URL}" rel="stylesheet">
    <style>
      @keyframes rp-rise { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
      @media (prefers-reduced-motion: no-preference) {
        .rp-rise { animation: rp-rise 0.7s cubic-bezier(0.2, 0.7, 0.2, 1) both; }
        .rp-d1 { animation-delay: 0.12s; }
        .rp-d2 { animation-delay: 0.24s; }
        .rp-d3 { animation-delay: 0.36s; }
      }
      @media (max-width: 480px) {
        .rp-card { padding: 28px 22px !important; border-radius: 24px !important; }
        .rp-heading { font-size: 22px !important; }
      }
    </style>
  </head>
  <body style="margin:0;padding:0;background:${EMAIL_COLORS.background};">
    <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(preheader)}</div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${EMAIL_COLORS.background};">
      <tr>
        <td align="center" style="padding:24px 12px 32px 12px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;">
            <tr>
              <td align="center" background="${mapUrl}" class="rp-rise" style="height:168px;padding:0 16px;vertical-align:middle;border-radius:32px 32px 0 0;background-color:${EMAIL_COLORS.background};background-image:url('${mapUrl}');background-position:center top;background-size:cover;background-repeat:no-repeat;">
                <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;">
                  <tr>
                    <td style="padding:12px 22px;border-radius:999px;background:${EMAIL_COLORS.card};border:1px solid ${EMAIL_COLORS.border};">
                      <img src="${logoUrl}" width="128" height="32" alt="Reporty" style="display:block;width:128px;height:32px;border:0;">
                    </td>
                  </tr>
                </table>
                ${monoLabel("p", "Posadas · Misiones", EMAIL_COLORS.accentForeground, "margin:12px 0 0 0;")}
              </td>
            </tr>
            <tr>
              <td class="rp-card rp-rise rp-d1" style="padding:36px 34px;background:${EMAIL_COLORS.card};border:1px solid ${EMAIL_COLORS.border};border-radius:32px;box-shadow:0 22px 70px -32px rgba(21,20,15,0.45);">
                ${monoLabel("p", kicker, EMAIL_COLORS.primary, "margin:0 0 10px 0;")}
                <h1 class="rp-heading" style="margin:0 0 18px 0;font-family:${FONT_SANS};font-size:26px;font-weight:700;line-height:1.2;letter-spacing:-0.6px;color:${EMAIL_COLORS.foreground};">${escapeHtml(heading)}</h1>
                ${body}
              </td>
            </tr>
            <tr>
              <td align="center" style="padding:22px 16px 0 16px;font-family:${FONT_SANS};font-size:12px;line-height:1.6;color:${EMAIL_COLORS.mutedForeground};">
                ${footnote ? `<p style="margin:0 0 10px 0;">${footnote}</p>` : ""}
                ${monoLabel("p", "Reporty · reportes ciudadanos de Posadas", EMAIL_COLORS.mutedForeground, "margin:0;font-size:10px;")}
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`
}
